# Applies result-screen patterns from top health apps (Appllama library): range bars with a position dot, one-line meaning per marker,
# a "N of M need attention" line in the verdict, dot-style status chips. Run: python3 _funnel_build/patch_appllama.py <files...>
import sys,re
HELPERS=r'''function chipFor(f){ if(f.color==='green') return 'ok'; if(f.color==='yellow') return 'warn'; return 'bad'; }
// Range bars: [min,max] scale and colour bands [upper bound, colour]; the dot marks the member's value. Thresholds = the signed threshold table.
const RANGES={Glucose:{min:4,max:12,bands:[[5.7,'#2a9d6f'],[6.5,'#d99a00'],[9.5,'#e07a1f'],[12,'#d9534f']],pick:(p,R)=>p.hba1c,alt:{min:60,max:260,bands:[[100,'#2a9d6f'],[126,'#d99a00'],[200,'#e07a1f'],[260,'#d9534f']],pick:(p,R)=>p.fpg}},
 'Blood pressure':{min:90,max:200,bands:[[120,'#2a9d6f'],[140,'#d99a00'],[160,'#e07a1f'],[200,'#d9534f']],pick:(p,R)=>p.sbp},
 Lipids:{min:50,max:250,bands:[[100,'#2a9d6f'],[130,'#d99a00'],[160,'#e07a1f'],[250,'#d9534f']],pick:(p,R)=>p.ldl},
 BMI:{min:15,max:40,bands:[[18.5,'#7aa7d9'],[23,'#2a9d6f'],[25,'#d99a00'],[30,'#e07a1f'],[40,'#d9534f']],pick:(p,R)=>R.derived.bmi},
 Kidney:{min:0,max:130,bands:[[30,'#d9534f'],[60,'#e07a1f'],[90,'#d99a00'],[130,'#2a9d6f']],pick:(p,R)=>R.derived.egfr},
 Liver:{min:0,max:200,bands:[[40,'#2a9d6f'],[80,'#d99a00'],[200,'#e07a1f']],pick:(p,R)=>Math.max(p.alt||0,p.ast||0)||null}};
function rangeBar(domain,p,R){ let cfg=RANGES[domain]; if(!cfg) return ''; let v=cfg.pick(p,R); if(v==null&&cfg.alt){ cfg=cfg.alt; v=cfg.pick(p,R); } if(v==null||isNaN(v)) return '';
  const span=cfg.max-cfg.min; const pos=Math.max(0,Math.min(1,(v-cfg.min)/span)); let lo=cfg.min;
  const segs=cfg.bands.map(([hi,c])=>{ const w=(Math.min(hi,cfg.max)-lo)/span*100; lo=Math.min(hi,cfg.max); return `<i style="flex:0 0 ${w}%;background:${c}"></i>`; }).join('');
  return `<div class="rb" aria-hidden="true"><div class="rbt">${segs}</div><b style="left:${(pos*100).toFixed(1)}%"></b></div>`; }
function attention(R){ const d=T(); const ks=R.findings.filter(f=>d.domain[f.domain]); const n=ks.filter(f=>f.color!=='green').length; return {n,m:ks.length}; }'''
PAGE_MARKERS_OLD='''h+=`<div class="markers">${keep.map(f=>`<div class="mk"><div class="l">${d.domain[f.domain]}</div><div class="v">${f.domain==='Tobacco'?(lang==='id'?'Ya':'Yes'):esc(f.value.replace(/^(HbA1c|FPG|LDL|eGFR)\\s/,''))}</div><div class="n">${d.normal[f.domain]||''}</div><span class="chip ${chipFor(f)}">${esc(d.stage[f.stage]||f.stage)}</span></div>`).join('')}</div>`;'''
PAGE_MARKERS_NEW='''h+=`<div class="markers">${keep.map(f=>`<div class="mk"><div class="l">${d.domain[f.domain]}</div><div class="v">${f.domain==='Tobacco'?(lang==='id'?'Ya':'Yes'):esc(f.value.replace(/^(HbA1c|FPG|LDL|eGFR)\\s/,''))} <span class="chip ${chipFor(f)}">${esc(d.stage[f.stage]||f.stage)}</span></div>${rangeBar(f.domain,p,R)}<div class="n">${d.normal[f.domain]||''}</div>${d.expl[f.domain]?`<div class="x">${d.expl[f.domain]}</div>`:''}</div>`).join('')}</div>`;'''
PAGE_VERDICT_OLD='''let h=`<h2 class="center">${d['r.h2']}</h2><div class="verdict" style="background:${VBG[R.tier.key]}"><div class="dot">${VIC[R.tier.key]}</div><div><h2>${V[0]}</h2><p>${V[1]}</p></div></div>`;'''
PAGE_VERDICT_NEW='''const att=attention(R); let h=`<h2 class="center">${d['r.h2']}</h2><div class="verdict" style="background:${VBG[R.tier.key]}"><div class="dot">${VIC[R.tier.key]}</div><div><h2>${V[0]}</h2><p>${V[1]}</p><p class="cnt">${d['r.count'](att.n,att.m)}</p></div></div>`;'''
REP_TABLE_OLD='''body+=`<table><tr><th>${lang==='id'?'Pemeriksaan':'Test'}</th><th>${d.rep.value}</th><th>${d.rep.status}</th><th>${lang==='id'?'Batas normal':'Normal range'}</th></tr>${R.findings.filter(f=>d.domain[f.domain]).map(f=>`<tr><td>${d.domain[f.domain]}</td><td>${f.domain==='Tobacco'?(lang==='id'?'Ya':'Yes'):esc(f.value)}</td><td>${esc(d.stage[f.stage]||f.stage)}</td><td>${d.normal[f.domain]||''}</td></tr>`).join('')}</table>`;'''
REP_TABLE_NEW='''body+=`<div class="markers">${R.findings.filter(f=>d.domain[f.domain]).map(f=>`<div class="mk"><div class="l">${d.domain[f.domain]}</div><div class="v">${f.domain==='Tobacco'?(lang==='id'?'Ya':'Yes'):esc(f.value.replace(/^(HbA1c|FPG|LDL|eGFR)\\s/,''))} <span class="chip ${chipFor(f)}">${esc(d.stage[f.stage]||f.stage)}</span></div>${rangeBar(f.domain,p,R)}<div class="n">${d.normal[f.domain]||''}</div>${d.expl[f.domain]?`<div class="x">${d.expl[f.domain]}</div>`:''}</div>`).join('')}</div>`;'''
REP_BAND_OLD='''body+=`<h2>${d.rep.single}${p.name?' · '+esc(p.name):''}</h2><div class="band" style="background:${TC[R.tier.key]}"><b>${V[0]}</b><br>${V[1]}</div>`;'''
REP_BAND_NEW='''const att=attention(R); body+=`<h2>${d.rep.single}${p.name?' · '+esc(p.name):''}</h2><div class="band" style="background:${TC[R.tier.key]}"><div class="bigv">${att.n}<small>/${att.m}</small></div><div><b>${V[0]}</b>${V[1]}<div class="cnt">${d['r.count'](att.n,att.m)}</div></div></div>`;'''
PAGE_CSS_OLD='.chip{display:inline-block;font-size:12px;font-weight:700;padding:3px 10px;border-radius:999px;white-space:nowrap}'
PAGE_CSS_NEW='''.chip{display:inline-block;font-size:12px;font-weight:700;padding:3px 10px;border-radius:999px;white-space:nowrap;vertical-align:middle}
.chip.ok::before,.chip.warn::before,.chip.bad::before{content:'';display:inline-block;width:7px;height:7px;border-radius:50%;background:currentColor;margin-right:6px;vertical-align:1px}
.mk .v{display:flex;align-items:center;gap:8px;flex-wrap:wrap}.mk .x{font-size:12px;color:var(--body);margin-top:6px;line-height:1.45}
.rb{position:relative;height:18px;margin:8px 0 4px}.rbt{display:flex;height:6px;border-radius:3px;overflow:hidden;margin-top:6px}.rbt i{display:block;height:100%}.rb b{position:absolute;top:1px;width:16px;height:16px;margin-left:-8px;border-radius:50%;background:#fff;border:3px solid var(--navy);box-shadow:0 1px 3px rgba(0,0,0,.25)}
.verdict .cnt{margin-top:6px;font-size:13px;font-weight:700;opacity:.95}'''
REP_CSS_OLD=".band{color:#fff;padding:16px 18px;border-radius:16px;margin:12px 0 16px;font-size:14.5px}.band b{font-size:17px;display:block;margin-bottom:2px}"
REP_CSS_NEW=""".band{color:#fff;padding:16px 18px;border-radius:16px;margin:12px 0 16px;font-size:14.5px;display:grid;grid-template-columns:auto 1fr;gap:16px;align-items:center}.band b{font-size:17px;display:block;margin-bottom:2px}.band .bigv{font-size:40px;font-weight:800;line-height:1;background:rgba(255,255,255,.18);border-radius:14px;padding:12px 14px;min-width:84px;text-align:center}.band .bigv small{font-size:16px;font-weight:600;opacity:.85}.band .cnt{margin-top:6px;font-size:13px;font-weight:700}
  .mk .v{display:flex;align-items:center;gap:8px;flex-wrap:wrap}.mk .x{font-size:11.5px;color:var(--body);margin-top:6px;line-height:1.45}.chip.ok{background:#dff3ea;color:#2a9d6f}.chip.warn{background:#fff3cf;color:#b88100}.chip.bad{background:#fde3e2;color:#d9534f}.chip.ok::before,.chip.warn::before,.chip.bad::before{content:'';display:inline-block;width:7px;height:7px;border-radius:50%;background:currentColor;margin-right:6px;vertical-align:1px}
  .rb{position:relative;height:18px;margin:8px 0 4px}.rbt{display:flex;height:6px;border-radius:3px;overflow:hidden;margin-top:6px}.rbt i{display:block;height:100%}.rb b{position:absolute;top:1px;width:16px;height:16px;margin-left:-8px;border-radius:50%;background:#fff;border:3px solid var(--navy);box-shadow:0 1px 3px rgba(0,0,0,.25)}"""
I18N_ID=("rep:{title:'Laporan Hasil MCU'", "'r.count':(n,m)=>n?`${n} dari ${m} pemeriksaan perlu perhatian`:`Semua ${m} pemeriksaan dalam batas normal`,expl:{Glucose:'Gula darah rata-rata 3 bulan terakhir. Makin tinggi, makin besar beban pada pembuluh darah, ginjal, dan mata.','Blood pressure':'Tekanan pada dinding pembuluh darah. Tinggi terus-menerus membebani jantung dan ginjal, sering tanpa gejala.',Lipids:'Kolesterol \\'jahat\\' yang menumpuk di dinding pembuluh darah. Pemicu utama serangan jantung dan stroke.',BMI:'Berat terhadap tinggi badan. Batas untuk orang Asia lebih ketat karena risiko diabetes muncul lebih awal.',Kidney:'Seberapa baik ginjal menyaring darah. Turun pelan-pelan tanpa terasa; diabetes dan hipertensi penyebab terbanyak.',Liver:'Enzim hati. Naik biasanya karena perlemakan hati, yang membaik dengan turun berat badan.',Tobacco:'Satu perubahan dengan dampak terbesar pada risiko jantung dan stroke.'},rep:{title:'Laporan Hasil MCU'")
I18N_EN=("rep:{title:'MCU Results Report'", "'r.count':(n,m)=>n?`${n} of ${m} tests need attention`:`All ${m} tests within the normal range`,expl:{Glucose:'Your average blood sugar over the last 3 months. The higher it is, the more strain on blood vessels, kidneys and eyes.','Blood pressure':'The pressure on your artery walls. Persistently high, it strains the heart and kidneys, usually without symptoms.',Lipids:'The \\'bad\\' cholesterol that builds up in artery walls. A main driver of heart attack and stroke.',BMI:'Weight relative to height. Cut-offs for Asian populations are stricter because diabetes risk starts earlier.',Kidney:'How well your kidneys filter blood. It declines slowly and silently; diabetes and hypertension are the usual causes.',Liver:'Liver enzymes. Usually raised by fatty liver, which improves with weight loss.',Tobacco:'The single change with the biggest effect on heart and stroke risk.'},rep:{title:'MCU Results Report'")
for f in sys.argv[1:]:
    s=open(f).read(); n0=len(s)
    for old,new in [("function chipFor(f){ if(f.color==='green') return 'ok'; if(f.color==='yellow') return 'warn'; return 'bad'; }",HELPERS),(PAGE_MARKERS_OLD,PAGE_MARKERS_NEW),(PAGE_VERDICT_OLD,PAGE_VERDICT_NEW),(REP_TABLE_OLD,REP_TABLE_NEW),(REP_BAND_OLD,REP_BAND_NEW),(PAGE_CSS_OLD,PAGE_CSS_NEW),(REP_CSS_OLD,REP_CSS_NEW),I18N_ID,I18N_EN]:
        assert s.count(old)==1,(f,old[:60],s.count(old)); s=s.replace(old,new,1)
    open(f,'w').write(s); print('patched',f,n0,'->',len(s))
